using System;using System.IO;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Net;
class TitleArtwork{
static int Main(string[] args){try{if(args.Length<1)return 1;string root=AppDomain.CurrentDomain.BaseDirectory,app=Path.GetFullPath(Path.Combine(root,".."));var p=new Process();p.StartInfo=new ProcessStartInfo(Path.Combine(app,"node.exe"),"\""+Path.Combine(app,"title-artwork.cjs")+"\" \""+args[0]+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true};p.Start();string output=p.StandardOutput.ReadToEnd();p.WaitForExit();var j=new JavaScriptSerializer();var v=j.Deserialize<Dictionary<string,object>>(output);if(!v.ContainsKey("url"))return 0;var uri=new Uri((string)v["url"]);if(uri.Scheme!="https"||uri.Host!="image.tmdb.org")return 1;uri=new Uri(uri.AbsoluteUri.Replace("/t/p/original/","/t/p/w500/"));string dir=Environment.GetEnvironmentVariable("FUA_DATA_DIR");if(String.IsNullOrEmpty(dir))dir=Path.Combine(app,"data");dir=Path.Combine(dir,"title-logo-cache");Directory.CreateDirectory(dir);string basefile=Path.Combine(dir,(string)v["key"]+"-compact");if(!File.Exists(basefile+".json")||!File.Exists(basefile+".bgra")){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;byte[] data;using(var client=new WebClient())data=client.DownloadData(uri);using(var stream=new MemoryStream(data))using(var image=new Bitmap(stream)){int w=Math.Min(500,image.Width),h=Math.Max(1,(int)Math.Round(image.Height*(double)w/image.Width));if(h>180){w=Math.Max(1,(int)Math.Round(w*180.0/h));h=180;}using(var b=new Bitmap(w,h,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(b)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(image,0,0,w,h);}var bits=b.LockBits(new Rectangle(0,0,w,h),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);byte[] raw=new byte[w*h*4];for(int y=0;y<h;y++)Marshal.Copy(IntPtr.Add(bits.Scan0,y*bits.Stride),raw,y*w*4,w*4);b.UnlockBits(bits);File.WriteAllBytes(basefile+".bgra",raw);File.WriteAllText(basefile+".json",j.Serialize(new{width=w,height=h,file=basefile+".bgra"}));}}}Console.Write(File.ReadAllText(basefile+".json"));return 0;}catch{return 1;}}
}